// DB-backed session-transcript merge: each checkpoint contributes its cached
// `transcript_stripped` slice and messages are deduped across checkpoints.
// Callers with auth context (the `/transcript` endpoint) can fall back to
// GitHub on cold cache; the public resolver can't, which is why the fallback
// lives at the call site rather than here.

import type { SessionAttribution, SkillEvent, TranscriptMessage } from "../types"
import { LEGACY_FALLBACK_AGENT_NAME } from "./constants"
import {
  annotateMessagesWithSkillEvents,
  dedupeSkillEvents,
  filterSkillEventsForTranscriptWindow,
  normalizeSkillEvents,
} from "./skill-events"
import {
  parseStoredTranscriptSessions,
  shouldUseUnifiedParserForStoredSession,
} from "./stored-transcript"
import { getParserForAgent, filterRelevantMessages, type ParserOptions } from "./transcript-parsers"

export interface SessionTranscriptCheckpointRow {
  checkpoint_id: string
  sessions: string | null
  transcript_stripped: string | null
  storage_version: number | null
}

interface ParsedCheckpointSession {
  agent?: string
  sessionId?: string
  transcriptIdentifierAtStart?: string
  checkpointTranscriptStart?: number | null
  tokenUsage?: { inputTokens?: number; outputTokens?: number }
  attribution?: {
    calculatedAt?: string
    agentLines?: number
    humanAdded?: number
    humanModified?: number
    humanRemoved?: number
    totalCommitted?: number
    agentPercentage?: number
  }
  skillEvents?: SkillEvent[]
  skill_events?: unknown[]
}

export interface MergedSessionTranscript {
  messages: TranscriptMessage[]
  agent: string
  tokenUsage?: { inputTokens: number; outputTokens: number }
  attribution?: SessionAttribution
  skillEvents?: SkillEvent[]
  /**
   * The parsed `sessions` JSON for each input checkpoint (same order). The
   * authenticated transcript endpoint reuses this for its GitHub fallback so
   * it doesn't have to re-parse.
   */
  checkpointSessionsInfo: Array<ParsedCheckpointSession[] | null>
}

export function mergeSessionTranscript(
  checkpoints: SessionTranscriptCheckpointRow[],
  sessionId: string,
): MergedSessionTranscript {
  const messages: TranscriptMessage[] = []
  const seenMessageIds = new Set<string>()
  let agent = LEGACY_FALLBACK_AGENT_NAME
  let tokenUsage: MergedSessionTranscript["tokenUsage"]
  let attribution: SessionAttribution | undefined
  const collectedSkillEvents: SkillEvent[] = []

  const checkpointSessionsInfo: Array<ParsedCheckpointSession[] | null> = checkpoints.map((cp) => {
    if (!cp.sessions) return null
    try {
      return JSON.parse(cp.sessions) as ParsedCheckpointSession[]
    } catch {
      return null
    }
  })

  for (let cpIdx = 0; cpIdx < checkpoints.length; cpIdx++) {
    const cp = checkpoints[cpIdx]
    const sessionsInfo = checkpointSessionsInfo[cpIdx]
    if (!sessionsInfo) continue

    const sessionIndex = sessionsInfo.findIndex((s) => s.sessionId === sessionId)
    if (sessionIndex === -1) continue

    // Per-checkpoint metadata (agent / tokenUsage / attribution) lives in
    // `cp.sessions`, which is present on every row, NOT in the transcript
    // blob. Accumulate it independent of whether we have transcript content
    // — otherwise the latest-only fetch in getCheckpointsForSession would
    // under-count tokens by skipping earlier checkpoints' deltas.
    const meta = sessionsInfo[sessionIndex]
    const checkpointAgent = meta.agent ?? LEGACY_FALLBACK_AGENT_NAME
    agent = checkpointAgent

    if (meta.tokenUsage) {
      const prev = tokenUsage ?? { inputTokens: 0, outputTokens: 0 }
      tokenUsage = {
        inputTokens: prev.inputTokens + (meta.tokenUsage.inputTokens ?? 0),
        outputTokens: prev.outputTokens + (meta.tokenUsage.outputTokens ?? 0),
      }
    }

    if (meta.attribution) {
      attribution = {
        calculatedAt: meta.attribution.calculatedAt ?? "",
        agentLines: meta.attribution.agentLines ?? 0,
        humanAdded: meta.attribution.humanAdded ?? 0,
        humanModified: meta.attribution.humanModified ?? 0,
        humanRemoved: meta.attribution.humanRemoved ?? 0,
        totalCommitted: meta.attribution.totalCommitted ?? 0,
        agentPercentage: meta.attribution.agentPercentage ?? 0,
      }
    }

    const skillEvents = filterSkillEventsForTranscriptWindow(
      meta.skillEvents ?? normalizeSkillEvents(meta.skill_events),
      meta.checkpointTranscriptStart,
    )
    if (skillEvents.length > 0) collectedSkillEvents.push(...skillEvents)

    // Below this point we need the actual transcript content to parse
    // messages out of it.
    if (!cp.transcript_stripped) continue

    const strippedMap = parseStoredTranscriptSessions(cp.transcript_stripped)
    if (!strippedMap) continue

    const storedSession = strippedMap[String(sessionIndex)]
    const jsonl = storedSession?.content
    if (!jsonl) continue

    const sessionParserOptions: ParserOptions | undefined = shouldUseUnifiedParserForStoredSession(
      storedSession,
      cp.storage_version,
    )
      ? { enableUnifiedTranscriptParser: true }
      : undefined
    const parseResult = getParserForAgent(checkpointAgent, sessionParserOptions).parse(jsonl)
    const filtered = filterRelevantMessages(
      parseResult.messages,
      meta.transcriptIdentifierAtStart ?? null,
    )

    for (const msg of filtered) {
      if (seenMessageIds.has(msg.id)) continue
      seenMessageIds.add(msg.id)
      messages.push(msg)
    }
  }

  const skillEvents = dedupeSkillEvents(collectedSkillEvents)
  return {
    messages: annotateMessagesWithSkillEvents(messages, skillEvents),
    agent,
    tokenUsage,
    attribution,
    skillEvents: skillEvents.length > 0 ? skillEvents : undefined,
    checkpointSessionsInfo,
  }
}

